    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_scratchpad_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_classify_paste() != 1460) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_evaluate_table() != 24864) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_export_everything() != 33114) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_export_json() != 4221) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_export_sheet() != 13983) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_export_table() != 22296) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_scratchpad_ffi_checksum_func_export_todos() != 18080) {
